package com.smarthub.plus;
import android.app.Activity;import android.content.*;import android.content.pm.*;import android.content.res.*;import android.os.Bundle;import org.xmlpull.v1.XmlPullParser;import java.util.*;
/** Reads published OEM menu resources and opens exported Android components only. */
final class ManufacturerFeatures {
 static final String OEM="com.tosmart.aurum",NS="http://schemas.android.com/apk/res-auto";
 static final class Entry {final String id,title,source;final Intent intent;Entry(String id,String title,String source,Intent intent){this.id=id;this.title=title;this.source=source;this.intent=intent;}}
 static List<Entry> read(Context c){List<Entry> out=new ArrayList<>();try{Resources r=c.getPackageManager().getResourcesForApplication(OEM);int id=r.getIdentifier("dvb_host_main_menu","xml",OEM);if(id!=0)try(XmlResourceParser x=r.getXml(id)){int n=0;while(x.next()!=XmlPullParser.END_DOCUMENT){if(x.getEventType()!=XmlPullParser.START_TAG||(!x.getName().equals("item")&&!x.getName().equals("child")))continue;if(++n>128)break;if("false".equalsIgnoreCase(attr(x,"host_visible")))continue;String key=attr(x,"host_id"),title=attr(x,"host_title");int titleId=x.getAttributeResourceValue(NS,"host_title",0);if(titleId!=0)title=r.getString(titleId);String action=attr(x,"host_action"),component=attr(x,"host_component_name"),pkg="true".equalsIgnoreCase(attr(x,"host_use_current_package"))?OEM:attr(x,"host_package_name");Intent i=new Intent();if(!action.isEmpty())i.setAction(action);if(!component.isEmpty()){ComponentName target=component.contains("/")?ComponentName.unflattenFromString(component):new ComponentName(pkg.isEmpty()?OEM:pkg,component);if(target!=null)i.setComponent(target);}else if(!pkg.isEmpty())i.setPackage(pkg);if(!action.startsWith("android.settings.")&&i.getComponent()==null&&i.getPackage()==null)i.setPackage(OEM);Bundle bundle=parseBundle(attr(x,"host_bundle"));if(!bundle.isEmpty()){bundle.putBoolean("from_home",true);bundle.putBoolean("from_home_as_app",true);i.putExtras(bundle);}if(!title.isEmpty()&&(!action.isEmpty()||i.getComponent()!=null))out.add(new Entry("xml:"+key,title,"OEM XML",i));}}}catch(Exception unavailable){}
  add(out,"server","Server Settings",host(true,"Other_Module",0,0));add(out,"ca","CA Menu",host(true,"Other_Module",0,0));add(out,"patch","Patch Menu",host(true,"Other_Module",0,0));add(out,"homeshare","Home Share",host(true,"Other_Module",0,0));
  add(out,"satellite","Satellite / LNB / scanning",host(false,"Search_Channel",1,0));
  if(hasFragment(c,"nav_installation","SatelliteMotorFragment"))add(out,"motor","Motor · DiSEqC / USALS (firmware)",host(false,"Search_Channel",1,33));
  add(out,"edit_tv","Edit TV channels",host(false,"Edit_Channel",50,0));add(out,"edit_radio","Edit radio channels",host(false,"Edit_Channel",51,0));add(out,"edit_favorites","Edit channel favourites",host(false,"Edit_Channel",52,0));add(out,"sort_channels","Sort channels",host(false,"Edit_Channel",54,0));add(out,"channel_backup","Channel file / backup",host(false,"Edit_Channel",55,0));
  add(out,"native_tv_controls","Original TV · DVB / TXT / audio",ReceiverNavigation.television());add(out,"epg_pro","EPG Pro",new Intent("com.tosmart.action.epg_pro").setPackage(OEM));
  Intent files=c.getPackageManager().getLaunchIntentForPackage("com.tosmart.filemanagerpro");if(files!=null)add(out,"usb_files","USB / files",files);
  Intent media=c.getPackageManager().getLaunchIntentForPackage("com.tosmart.localplayer");if(media!=null)add(out,"usb_media","USB media player",media);
  return out;
 }
 static boolean hasFragment(Context c,String graph,String suffix){try{Resources r=c.getPackageManager().getResourcesForApplication(OEM);int id=r.getIdentifier(graph,"navigation",OEM);if(id==0)return false;try(XmlResourceParser x=r.getXml(id)){while(x.next()!=XmlPullParser.END_DOCUMENT)if(x.getEventType()==XmlPullParser.START_TAG&&x.getAttributeValue("http://schemas.android.com/apk/res/android","name")!=null&&x.getAttributeValue("http://schemas.android.com/apk/res/android","name").endsWith("."+suffix))return true;}}catch(Exception unavailable){}return false;}
 static Entry find(Context c,String id){for(Entry e:read(c))if(e.id.equals(id))return e;return null;}
 private static void add(List<Entry> out,String id,String title,Intent i){out.add(new Entry(id,title,"OEM navigation",i));}
 static Intent host(boolean extension,String category,int sub,int type){Bundle b=new Bundle();b.putBoolean("from_home",true);b.putBoolean("from_home_as_app",true);b.putString("host_type",category);b.putInt("sub_host_type",sub);b.putInt("enter_type",type);return new Intent(extension?"com.tosmart.action.ExtNavHost":"com.tosmart.action.NavHost").setPackage(OEM).putExtras(b);}
 static String unavailable(Context c,Entry e){try{ResolveInfo resolved=c.getPackageManager().resolveActivity(e.intent,0);if(resolved==null||resolved.activityInfo==null)return "NOT_INSTALLED";ActivityInfo a=resolved.activityInfo;if(!a.exported)return "PRIVATE_OEM_COMPONENT";if(!a.enabled||!a.applicationInfo.enabled)return "DISABLED";if(a.permission!=null&&c.checkSelfPermission(a.permission)!=PackageManager.PERMISSION_GRANTED)return "OEM_PERMISSION_REQUIRED";return "";}catch(Exception failure){return "UNAVAILABLE";}}
 static boolean open(Context c,Entry e){if(e==null||!unavailable(c,e).isEmpty())return false;try{Intent i=new Intent(e.intent);i.setFlags(0);if(!(c instanceof Activity))i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);android.content.SharedPreferences.Editor save=c.getSharedPreferences("smarthub",0).edit().putBoolean("own_dvb_restore_after_oem",true);if(Arrays.asList("server","ca","patch","homeshare").contains(e.id)){save.putString("oem_pending_route",e.id).putLong("oem_pending_until",System.currentTimeMillis()+6000);}save.apply();c.startActivity(i);return true;}catch(ActivityNotFoundException|SecurityException refused){return false;}}

 /** Selects a static item in the original sidebar, through its normal focus/click handlers. */
 static boolean navigateSidebar(Context c,android.view.accessibility.AccessibilityNodeInfo root){android.content.SharedPreferences p=c.getSharedPreferences("smarthub",0);String route=p.getString("oem_pending_route","");long left=p.getLong("oem_pending_until",0)-System.currentTimeMillis();if(route.isEmpty())return false;if(left<=0||left>6000){p.edit().remove("oem_pending_route").remove("oem_pending_until").apply();return false;}if(root==null||!OEM.contentEquals(root.getPackageName()))return false;String resource=route.equals("server")?"STR_SERVER_SETTING":route.equals("ca")?"STR_CA_MENU":route.equals("patch")?"STR_PT_MENU":route.equals("homeshare")?"STR_HOME_SHR":"";if(resource.isEmpty())return false;List<android.view.accessibility.AccessibilityNodeInfo> side=new ArrayList<>(root.findAccessibilityNodeInfosByViewId(OEM+":id/left_rv_menu_content"));boolean acted=false;try{Resources r=c.getPackageManager().getResourcesForApplication(OEM);int id=r.getIdentifier(resource,"string",OEM);if(id==0)return false;String label=r.getString(id);if(side.isEmpty()){boolean menu=true;for(String key:new String[]{"STR_CA_MENU","STR_SERVER_SETTING","STR_PT_MENU"}){int titleId=r.getIdentifier(key,"string",OEM);if(titleId==0){menu=false;break;}List<android.view.accessibility.AccessibilityNodeInfo> titles=root.findAccessibilityNodeInfosByText(r.getString(titleId));if(titles.isEmpty())menu=false;for(android.view.accessibility.AccessibilityNodeInfo title:titles)title.recycle();}if(menu)side.add(android.view.accessibility.AccessibilityNodeInfo.obtain(root));}boolean sidebar=!side.isEmpty()&&side.get(0).getViewIdResourceName()!=null&&side.get(0).getViewIdResourceName().endsWith("/left_rv_menu_content");for(android.view.accessibility.AccessibilityNodeInfo panel:side){List<android.view.accessibility.AccessibilityNodeInfo> targets=panel.findAccessibilityNodeInfosByText(label);for(android.view.accessibility.AccessibilityNodeInfo node:targets)try{if(node.getText()==null||!label.contentEquals(node.getText()))continue;android.view.accessibility.AccessibilityNodeInfo cursor=android.view.accessibility.AccessibilityNodeInfo.obtain(node);try{for(int depth=0;cursor!=null&&depth<4;depth++){if(sidebar&&cursor.isFocusable())acted|=cursor.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_FOCUS);if(cursor.isClickable())acted|=cursor.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);if(acted)break;android.view.accessibility.AccessibilityNodeInfo parent=cursor.getParent();cursor.recycle();cursor=parent;}}finally{if(cursor!=null)cursor.recycle();}if(acted)break;}finally{node.recycle();}if(acted)break;}if(acted)p.edit().remove("oem_pending_route").remove("oem_pending_until").putString("oem_last_navigation",route).putLong("oem_last_navigation_at",System.currentTimeMillis()).apply();return acted;}catch(Exception unavailable){return false;}finally{for(android.view.accessibility.AccessibilityNodeInfo panel:side)panel.recycle();}}
 private static String attr(XmlResourceParser x,String name){String s=x.getAttributeValue(NS,name);if(s==null)s=x.getAttributeValue(null,name);return s==null?"":s;}
 static Bundle parseBundle(String text){Bundle b=new Bundle();Set<String> allowed=new HashSet<>(Arrays.asList("from_home","from_home_as_app","host_type","sub_host_type","enter_type","fav_group_index","FUNCTION_TYPE","input_id"));for(String part:text.split(",")){String[] p=part.split(":",2);if(p.length!=2||!allowed.contains(p[0].trim()))continue;String k=p[0].trim(),v=p[1].trim();if(v.equalsIgnoreCase("true")||v.equalsIgnoreCase("false"))b.putBoolean(k,Boolean.parseBoolean(v));else if(v.matches("-?[0-9]{1,8}"))b.putInt(k,Integer.parseInt(v));else if(v.length()<=100)b.putString(k,v);}return b;}
}